const fs = require('fs');
const path = require('path');

const dataDir = path.join(__dirname, '..', 'data');
const files = fs.readdirSync(dataDir).filter(f => f.endsWith('.json')).sort();

let bundleEntries = '';
files.forEach(file => {
  const key = path.basename(file, '.json');
  const filePath = path.join(dataDir, file);
  const content = fs.readFileSync(filePath, 'utf8');

  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (err) {
    console.error(`FATAL: Invalid JSON in ${file}:`, err.message);
    process.exit(1);
  }

  // Minify JSON to eliminate whitespace overhead
  bundleEntries += `window.ROADMAP_DATA['${key}'] = ${JSON.stringify(parsed)};\n`;
});

const code = `/**
 * Chartered Roadmap - Bundled Datasets
 * Offline-friendly bundle ensuring roadmaps load instantly whether via HTTP(S) or local file:///
 * Automatically generated by scripts/bundle-data.js - DO NOT EDIT DIRECTLY
 */
window.ROADMAP_DATA = window.ROADMAP_DATA || {};
${bundleEntries}
window.ROADMAP_LOADER = {
  async get(id) {
    if (window.ROADMAP_DATA[id]) {
      return window.ROADMAP_DATA[id];
    }
    try {
      const res = await fetch(\`data/\${id}.json\`);
      if (!res.ok) throw new Error(\`HTTP \${res.status}\`);
      const json = await res.json();
      window.ROADMAP_DATA[id] = json;
      return json;
    } catch (e) {
      console.warn(\`Local fetch fallback for \${id}:\`, e);
      return window.ROADMAP_DATA[id] || null;
    }
  }
};
`;

fs.writeFileSync(path.join(dataDir, 'roadmaps.js'), code, 'utf8');
console.log(`roadmaps.js successfully generated with ${files.length} datasets: ${files.map(f => path.basename(f, '.json')).join(', ')}.`);
